USE master;
GO
IF NOT EXISTS (SELECT name FROM sys.databases WHERE name = N'RassaDB')
BEGIN
    CREATE DATABASE RassaDB;
END
GO
USE RassaDB;
GO
IF OBJECT_ID('OrderBlockchainLedger', 'U') IS NOT NULL DROP TABLE OrderBlockchainLedger;
IF OBJECT_ID('OrderItems', 'U') IS NOT NULL DROP TABLE OrderItems;
IF OBJECT_ID('Orders', 'U') IS NOT NULL DROP TABLE Orders;
IF OBJECT_ID('Inventory', 'U') IS NOT NULL DROP TABLE Inventory;
IF OBJECT_ID('Products', 'U') IS NOT NULL DROP TABLE Products;
IF OBJECT_ID('Warehouses', 'U') IS NOT NULL DROP TABLE Warehouses;
IF OBJECT_ID('Categories', 'U') IS NOT NULL DROP TABLE Categories;
IF OBJECT_ID('Users', 'U') IS NOT NULL DROP TABLE Users;
GO
CREATE TABLE Users (
    UserID INT IDENTITY(1,1) PRIMARY KEY,
    FullName NVARCHAR(100) NOT NULL,
    Phone NVARCHAR(20) NOT NULL,
    Email NVARCHAR(100) NOT NULL UNIQUE,
    PasswordHash NVARCHAR(256) NOT NULL,
    Role NVARCHAR(30) NOT NULL CHECK (Role IN (N'Admin', N'WarehouseManager', N'Client')),
    BusinessType NVARCHAR(50) NOT NULL,
    LocationZone NVARCHAR(100) NOT NULL,
    IsActive BIT NOT NULL DEFAULT 1,
    CreatedAt DATETIME NOT NULL DEFAULT GETDATE()
);
CREATE TABLE Categories (
    CategoryID INT IDENTITY(1,1) PRIMARY KEY,
    CategoryName NVARCHAR(100) NOT NULL,
    Description NVARCHAR(255) NULL,
    IconClass NVARCHAR(50) NOT NULL DEFAULT N'bi-box-seam'
);
CREATE TABLE Warehouses (
    WarehouseID INT IDENTITY(1,1) PRIMARY KEY,
    WarehouseName NVARCHAR(150) NOT NULL,
    Specialty NVARCHAR(150) NOT NULL,
    LocationZone NVARCHAR(100) NOT NULL,
    DistanceKm DECIMAL(5,2) NOT NULL DEFAULT 1.00,
    DeliveryStatus NVARCHAR(50) NOT NULL DEFAULT N'متاح الآن',
    ManagerUserID INT NOT NULL,
    IsActive BIT NOT NULL DEFAULT 1,
    CONSTRAINT FK_Warehouses_Users FOREIGN KEY (ManagerUserID) REFERENCES Users(UserID)
);
CREATE TABLE Products (
    ProductID INT IDENTITY(1,1) PRIMARY KEY,
    ProductName NVARCHAR(150) NOT NULL,
    Description NVARCHAR(500) NULL,
    SizeUnit NVARCHAR(50) NOT NULL,
    Price DECIMAL(18,2) NOT NULL CHECK (Price >= 0),
    ExpectedDeliveryTime NVARCHAR(100) NOT NULL DEFAULT N'اليوم - 06:00 مساءً',
    ImageUrl NVARCHAR(255) NULL,
    CategoryID INT NOT NULL,
    WarehouseID INT NOT NULL,
    CONSTRAINT FK_Products_Categories FOREIGN KEY (CategoryID) REFERENCES Categories(CategoryID),
    CONSTRAINT FK_Products_Warehouses FOREIGN KEY (WarehouseID) REFERENCES Warehouses(WarehouseID)
);
CREATE TABLE Inventory (
    InventoryID INT IDENTITY(1,1) PRIMARY KEY,
    ProductID INT NOT NULL UNIQUE,
    WarehouseID INT NOT NULL,
    AvailableQuantity INT NOT NULL CHECK (AvailableQuantity >= 0),
    MinThreshold INT NOT NULL DEFAULT 10,
    LastUpdated DATETIME NOT NULL DEFAULT GETDATE(),
    CONSTRAINT FK_Inventory_Products FOREIGN KEY (ProductID) REFERENCES Products(ProductID) ON DELETE CASCADE,
    CONSTRAINT FK_Inventory_Warehouses FOREIGN KEY (WarehouseID) REFERENCES Warehouses(WarehouseID)
);
CREATE TABLE Orders (
    OrderID INT IDENTITY(1,1) PRIMARY KEY,
    OrderNumber NVARCHAR(30) NOT NULL UNIQUE,
    ClientUserID INT NOT NULL,
    WarehouseID INT NOT NULL,
    OrderDate DATETIME NOT NULL DEFAULT GETDATE(),
    TotalAmount DECIMAL(18,2) NOT NULL CHECK (TotalAmount >= 0),
    OrderStatus NVARCHAR(50) NOT NULL DEFAULT N'تم تأكيد الطلب',
    EstimatedArrivalMinutes INT NOT NULL DEFAULT 25,
    DeliveryAddress NVARCHAR(255) NOT NULL,
    CONSTRAINT FK_Orders_ClientUser FOREIGN KEY (ClientUserID) REFERENCES Users(UserID),
    CONSTRAINT FK_Orders_Warehouse FOREIGN KEY (WarehouseID) REFERENCES Warehouses(WarehouseID)
);
CREATE TABLE OrderItems (
    OrderItemID INT IDENTITY(1,1) PRIMARY KEY,
    OrderID INT NOT NULL,
    ProductID INT NOT NULL,
    Quantity INT NOT NULL CHECK (Quantity > 0),
    UnitPrice DECIMAL(18,2) NOT NULL,
    SubTotal DECIMAL(18,2) NOT NULL,
    CONSTRAINT FK_OrderItems_Orders FOREIGN KEY (OrderID) REFERENCES Orders(OrderID) ON DELETE CASCADE,
    CONSTRAINT FK_OrderItems_Products FOREIGN KEY (ProductID) REFERENCES Products(ProductID)
);
CREATE TABLE OrderBlockchainLedger (
    BlockID INT IDENTITY(1,1) PRIMARY KEY,
    OrderID INT NOT NULL,
    BlockIndex INT NOT NULL,
    EventType NVARCHAR(100) NOT NULL,
    EventDescription NVARCHAR(300) NOT NULL,
    Timestamp DATETIME NOT NULL DEFAULT GETDATE(),
    PreviousHash NVARCHAR(128) NOT NULL,
    CurrentHash NVARCHAR(128) NOT NULL,
    CONSTRAINT FK_Blockchain_Orders FOREIGN KEY (OrderID) REFERENCES Orders(OrderID) ON DELETE CASCADE
);
GO
