-- إدخال أرصدة المخزون لجميع الـ 450 منتجاً (30 مخزن × 15 منتج)
SELECT ProductID, WarehouseID, 
       CASE WHEN ProductID = 1 THEN 24 WHEN ProductID % 9 = 0 THEN 7 ELSE 30 + (ProductID % 45) END,
       10
FROM Products;
